import React, { useState, useEffect, useMemo } from "react";
import {
  ResponsiveContainer,
  ScatterChart,
  Scatter,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Radar,
  RadarChart,
  PolarGrid,
  PolarAngleAxis,
  PolarRadiusAxis,
} from "recharts";
import HeatMap from "react-heatmap-grid";

export default function SeedCatalog() {
  const [data, setData] = useState([]);
  const [selected, setSelected] = useState([]);
  const [activeVariety, setActiveVariety] = useState(null);
  const [xTrait, setXTrait] = useState("yield_kg_ha");
  const [yTrait, setYTrait] = useState("maturity_days");

  useEffect(() => {
    fetch("/seed-catalog/data/uog-varieties-clean.json")
      .then((r) => r.json())
      .then(setData);
  }, []);

  const selectedRows = data.filter((d) =>
    selected.includes(d.id)
  );

  function toggleSelect(id) {
    setSelected((s) =>
      s.includes(id)
        ? s.filter((x) => x !== id)
        : s.length < 5
        ? [...s, id]
        : s
    );
  }

  // Resistance %
  function resistanceScore(r) {
    const vals = Object.values(r || {}).filter(
      (v) => v && v !== "N/A"
    );
    if (!vals.length) return 0;
    return (
      (vals.filter((v) => v === "R").length /
        vals.length) *
      100
    );
  }

  // Radar data
  const radarData = selectedRows.map((v) => ({
    name: v.name,
    Yield: v.yield_kg_ha || 0,
    Maturity: v.maturity_days || 0,
    "Seed weight": v.seed_weight_g || 0,
    Harvestability: v.harvestability || 0,
    Resistance: resistanceScore(v.resistance),
  }));

  // Heatmap data
  const diseases = [
    "CMV_R1",
    "CMV_R15",
    "Anthracnose_R17",
    "Anthracnose_R23",
    "Anthracnose_R73",
    "CommonBlight",
  ];

  const heatData = selectedRows.map((v) =>
    diseases.map((d) => {
      const val = v.resistance?.[d];
      if (val === "R") return 2;
      if (val === "S") return 0;
      return 1;
    })
  );

  // Scatter data
  const scatterData = selectedRows
    .filter(
      (d) =>
        typeof d[xTrait] === "number" &&
        typeof d[yTrait] === "number"
    )
    .map((d) => ({
      x: d[xTrait],
      y: d[yTrait],
      name: d.name,
    }));

  return (
    <div style={{ padding: 40 }}>
      <h1>Seed Analytics Dashboard</h1>

      {/* Variety selector */}
      <div style={{ display: "flex", flexWrap: "wrap" }}>
        {data.map((v) => (
          <label key={v.id} style={{ margin: 6 }}>
            <input
              type="checkbox"
              checked={selected.includes(v.id)}
              onChange={() => toggleSelect(v.id)}
            />
            {v.name}
          </label>
        ))}
      </div>

      {/* Comparison table */}
      {selectedRows.length > 0 && (
        <>
          <h2>Comparison Table</h2>
          <table border="1" cellPadding="6">
            <thead>
              <tr>
                <th>Name</th>
                <th>Yield</th>
                <th>Maturity</th>
                <th>Seed wt</th>
                <th>Harvest</th>
                <th>Resistance %</th>
              </tr>
            </thead>
            <tbody>
              {selectedRows.map((v) => (
                <tr key={v.id}>
                  <td
                    style={{ cursor: "pointer" }}
                    onClick={() => setActiveVariety(v)}
                  >
                    {v.name}
                  </td>
                  <td>{v.yield_kg_ha}</td>
                  <td>{v.maturity_days}</td>
                  <td>{v.seed_weight_g}</td>
                  <td>{v.harvestability}</td>
                  <td>
                    {resistanceScore(v.resistance).toFixed(0)}%
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </>
      )}

      {/* Radar */}
      {selectedRows.length > 1 && (
        <>
          <h2>Trait Radar</h2>
          <ResponsiveContainer width="100%" height={400}>
            <RadarChart data={radarData}>
              <PolarGrid />
              <PolarAngleAxis dataKey="name" />
              <PolarRadiusAxis />
              {radarData.map((_, i) => (
                <Radar
                  key={i}
                  dataKey="Yield"
                  stroke={`hsl(${i * 60},70%,50%)`}
                  fillOpacity={0.3}
                />
              ))}
            </RadarChart>
          </ResponsiveContainer>
        </>
      )}

      {/* Heatmap */}
      {selectedRows.length > 0 && (
        <>
          <h2>Resistance Heatmap</h2>
          <HeatMap
            data={heatData}
            xLabels={diseases}
            yLabels={selectedRows.map((v) => v.name)}
            cellStyle={(background, value) => ({
              background:
                value === 2
                  ? "#2ecc71"
                  : value === 0
                  ? "#e74c3c"
                  : "#bdc3c7",
            })}
          />
        </>
      )}

      {/* Scatter */}
      {selectedRows.length > 1 && (
        <>
          <h2>Scatter Comparison</h2>
          X:
          <select onChange={(e) => setXTrait(e.target.value)}>
            <option value="yield_kg_ha">Yield</option>
            <option value="maturity_days">Maturity</option>
            <option value="seed_weight_g">
              Seed weight
            </option>
            <option value="harvestability">
              Harvestability
            </option>
          </select>
          Y:
          <select onChange={(e) => setYTrait(e.target.value)}>
            <option value="maturity_days">
              Maturity
            </option>
            <option value="yield_kg_ha">Yield</option>
            <option value="seed_weight_g">
              Seed weight
            </option>
            <option value="harvestability">
              Harvestability
            </option>
          </select>

          <ResponsiveContainer width="100%" height={350}>
            <ScatterChart>
              <CartesianGrid />
              <XAxis dataKey="x" />
              <YAxis dataKey="y" />
              <Tooltip />
              <Scatter data={scatterData} fill="#3498db" />
            </ScatterChart>
          </ResponsiveContainer>
        </>
      )}

      {/* Variety profile */}
      {activeVariety && (
        <div
          onClick={() => setActiveVariety(null)}
          style={{
            position: "fixed",
            inset: 0,
            background: "rgba(0,0,0,0.7)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
          }}
        >
          <div
            onClick={(e) => e.stopPropagation()}
            style={{ background: "white", padding: 30, width: 600 }}
          >
            <h2>{activeVariety.name}</h2>

            <ul>
              <li>
                Market class:{" "}
                {activeVariety.marketClass}
              </li>
              <li>
                Yield: {activeVariety.yield_kg_ha}
              </li>
              <li>
                Maturity:{" "}
                {activeVariety.maturity_days}
              </li>
              <li>
                Seed weight:{" "}
                {activeVariety.seed_weight_g}
              </li>
              <li>
                Harvestability:{" "}
                {activeVariety.harvestability}
              </li>
              <li>
                Resistance %:{" "}
                {resistanceScore(
                  activeVariety.resistance
                ).toFixed(0)}
                %
              </li>
            </ul>

            <h4>Resistance profile</h4>
            <ul>
              {Object.entries(
                activeVariety.resistance
              ).map(([k, v]) => (
                <li key={k}>
                  {k}: {v}
                </li>
              ))}
            </ul>

            <button onClick={() => setActiveVariety(null)}>
              Close
            </button>
          </div>
        </div>
      )}
    </div>
  );
}